    ('a9ec0eaa-0b78-5a81-9267-0b5f74764918'::uuid, 'llcer-anglais', '1re', 'Imaginaires : le gothique et le fantastique', 'Quel est le sous-titre de *Frankenstein* ?', 'mcq', '["The Modern Faust","A Gothic Tale","The Last Man","The Modern Prometheus"]'::jsonb, 3, 'Comme Prométhée, Victor Frankenstein dérobe un pouvoir réservé aux dieux : donner la vie.', 4),
    ('654b5970-6598-53d6-92b4-d4d16aab5003'::uuid, 'llcer-anglais', '1re', 'Rencontres et société victorienne', 'Quel roman de Dickens met en accusation la ville industrielle et l’utilitarisme ?', 'mcq', '["*Hard Times*","*Oliver Twist*","*Great Expectations*","*David Copperfield*"]'::jsonb, 0, '*Hard Times* décrit Coketown et une éducation réduite aux « faits » : c’est la critique de l’utilitarisme.', 1),
    ('2a1467a6-b8ab-5279-a56e-05c31fe6c0ea'::uuid, 'llcer-anglais', '1re', 'Rencontres et société victorienne', 'Que désigne l’« entail » dans les romans du XIXe siècle ?', 'mcq', '["Une dot versée par le père de la mariée","Une rente viagère","Une substitution successorale qui prive les filles de l’héritage","Un contrat de mariage"]'::jsonb, 2, 'C’est le cas des Bennet dans *Pride and Prejudice* : le domaine doit revenir à un héritier mâle, d’où l’urgence de marier les filles.', 2),
    ('1b87d209-2ed7-5e61-bf19-571578981698'::uuid, 'llcer-anglais', '1re', 'Rencontres et société victorienne', 'Que revendique l’héroïne de *Jane Eyre* ?', 'mcq', '["Un riche héritage","D’être traitée en égale malgré sa pauvreté","Le droit de vote","La liberté de voyager seule"]'::jsonb, 1, 'Charlotte Brontë donne la parole à une héroïne pauvre qui exige d’être respectée comme une égale.', 3),
    ('b1a4f22f-4b83-5a52-a551-3e6027acc40d'::uuid, 'llcer-anglais', '1re', 'Rencontres et société victorienne', 'Comment fonctionne l’ironie du narrateur chez Jane Austen ?', 'mcq', '["Elle décrit les faits sans commentaire","Elle s’adresse directement au lecteur pour le sermonner","Elle raconte l’histoire à la première personne","Elle dit le contraire de ce qu’elle affirme et laisse le lecteur conclure"]'::jsonb, 3, 'La célèbre première phrase de *Pride and Prejudice* en est l’exemple : sous la « vérité universelle », on lit le marché du mariage.', 4),
    ('d250cee6-e57c-55ff-bc91-8bac8464c50c'::uuid, 'llcer-anglais', '1re', 'Méthode : commenter un texte en anglais', 'Que fait-on si l’on saute l’étape du « how » ?', 'mcq', '["Un hors-sujet","Un résumé","Une traduction","Une conclusion"]'::jsonb, 1, 'Sans l’analyse des moyens (lexical field, imagery, rhythm), on se contente de raconter : c’est l’erreur qui plafonne le plus vite une copie.', 1),
    ('2af4a884-23b7-57b0-90b6-8665e700b129'::uuid, 'llcer-anglais', '1re', 'Méthode : commenter un texte en anglais', 'Parmi ces mots, lequel désigne un ton ?', 'mcq', '["Setting","Omniscient","Satirical","Lexical field"]'::jsonb, 2, 'Ironic, nostalgic, satirical, detached sont des tons ; le setting est le cadre, omniscient un type de narrateur.', 2),
    ('978b1b83-7dee-50f7-a1ff-ca857c46da65'::uuid, 'llcer-anglais', '1re', 'Méthode : commenter un texte en anglais', 'Quelle expression sert à signaler un écho avec un autre passage ou une autre œuvre ?', 'mcq', '["This echoes…","To sum up…","The text deals with…","In contrast with…"]'::jsonb, 0, '« This echoes… » établit un rapprochement ; « In contrast with… » marque au contraire une opposition.', 3),
    ('109e85cc-ca6d-53f1-86e4-111b53795f69'::uuid, 'llcer-anglais', '1re', 'Méthode : commenter un texte en anglais', 'Comment doit être une citation dans un commentaire ?', 'mcq', '["Longue, pour montrer qu’on connaît le texte","Traduite en français","Paraphrasée librement","Exacte, courte et entre guillemets"]'::jsonb, 3, 'Une citation exacte et brève appuie l’analyse sans remplacer le commentaire.', 4),
    ('dee962d2-9fbb-57bd-b45d-0b026e23e335'::uuid, 'llcer-anglais', 'Tle', 'Expression et construction de soi', 'Qui a écrit *Their Eyes Were Watching God* (1937) ?', 'mcq', '["Maya Angelou","Zora Neale Hurston","Toni Morrison","Langston Hughes"]'::jsonb, 1, 'Zora Neale Hurston y fait de la langue vernaculaire noire une langue littéraire à part entière.', 1),
    ('ec88251c-474a-529d-b4b5-4c2387699dde'::uuid, 'llcer-anglais', 'Tle', 'Expression et construction de soi', 'Quel roman de Toni Morrison porte la mémoire de l’esclavage ?', 'mcq', '["*Beloved*","*I Know Why the Caged Bird Sings*","*Song of Myself*","*The Namesake*"]'::jsonb, 0, '*Beloved* (1987) raconte l’esclavage et ses traces ; Morrison reçoit le Nobel en 1993.', 2),
    ('ccf3890f-b5ad-503a-b996-c9802d761aa3'::uuid, 'llcer-anglais', 'Tle', 'Expression et construction de soi', 'Quel procédé est typique du discours *I Have a Dream* ?', 'mcq', '["Le monologue intérieur","L’euphémisme","L’anaphore","Le discours indirect libre"]'::jsonb, 2, 'La répétition de « I have a dream » en début de phrase, avec le rythme du prêche, donne au discours sa force.', 3),
    ('8dfda66a-b135-545f-a997-d2a61a036938'::uuid, 'llcer-anglais', 'Tle', 'Expression et construction de soi', 'Sur quoi repose l’autorité du discours de Malala Yousafzai à l’ONU en 2013 ?', 'mcq', '["Sur sa fonction de cheffe d’État","Sur des statistiques","Sur la citation de textes religieux","Sur le témoignage"]'::jsonb, 3, 'Victime d’un attentat pour avoir défendu l’école des filles, elle parle en témoin : son expérience fait autorité.', 4),
    ('29537261-4696-5c6f-a8ce-f86137d2033e'::uuid, 'llcer-anglais', 'Tle', 'Voyages, territoires, frontières', 'Qu’affirme la métaphore du « melting pot » ?', 'mcq', '["Chaque culture garde sa saveur","Tout fond dans un alliage commun : l’assimilation est la condition d’entrée","Les frontières doivent être fermées","Le migrant doit rentrer chez lui"]'::jsonb, 1, 'Le melting pot suppose l’assimilation ; le salad bowl, lui, admet que la différence n’empêche pas l’appartenance.', 1),
    ('b8712885-8f72-5a3b-90d6-396e95998250'::uuid, 'llcer-anglais', 'Tle', 'Voyages, territoires, frontières', 'Que raconte *Midnight’s Children* de Salman Rushdie ?', 'mcq', '["L’arrivée des colons dans un village igbo","La deuxième génération d’immigrés aux États-Unis","L’indépendance indienne racontée de l’intérieur","L’immigration irlandaise à Ellis Island"]'::jsonb, 2, 'Paru en 1981, le roman fait naître ses héros à minuit, le 15 août 1947, jour de l’indépendance de l’Inde.', 2),
    ('cdfc37d0-a1d2-5bde-8e84-90e33210b21d'::uuid, 'llcer-anglais', 'Tle', 'Voyages, territoires, frontières', 'Qu’est-il arrivé à une partie de la génération *Windrush* ?', 'mcq', '["Des citoyens britanniques ont été rendus illégaux rétroactivement","Ils ont été expulsés vers l’Australie","Ils ont obtenu la nationalité américaine","Ils ont fondé un nouvel État"]'::jsonb, 0, 'Arrivés des Caraïbes après 1948, certains se sont vu contester leur statut des décennies plus tard, faute de papiers.', 3),
    ('b4eaf919-9b66-526a-b7bf-8221490bac3c'::uuid, 'llcer-anglais', 'Tle', 'Voyages, territoires, frontières', 'Que signifie « settler » ?', 'mcq', '["Exilé","Frontalier","Réfugié","Colon"]'::jsonb, 3, 'Le « settler » s’installe sur une terre conquise ; « exile » désigne celui qui a dû quitter la sienne.', 4),
    ('0842dab1-0003-5550-9f41-b1981793d272'::uuid, 'llcer-anglais', 'Tle', 'L’épreuve de LLCER en terminale', 'Combien de temps dure l’oral de LLCER en terminale ?', 'mcq', '["10 minutes","20 minutes","30 minutes","1 heure"]'::jsonb, 1, 'L’oral dure 20 minutes : présentation d’un dossier personnel, puis entretien avec le jury.', 1),
    ('8a19da25-2f97-5ced-a5ae-661bda0e08fc'::uuid, 'llcer-anglais', 'Tle', 'L’épreuve de LLCER en terminale', 'Que contient la seconde partie de l’écrit ?', 'mcq', '["Une traduction ou une transposition d’un court passage","Un commentaire de texte","Un QCM de vocabulaire","Une dissertation en français"]'::jsonb, 0, 'Après la synthèse, l’élève traduit ou transpose un court passage.', 2),
    ('57a62d47-0d47-523c-86a9-0a5fe89a9016'::uuid, 'llcer-anglais', 'Tle', 'L’épreuve de LLCER en terminale', 'Selon le cours, d’où vient la moitié des points perdus ?', 'mcq', '["D’un vocabulaire trop simple","D’une copie trop courte","D’une consigne mal lue","D’une écriture illisible"]'::jsonb, 2, 'Connaître le format de l’épreuve fait partie de la préparation : beaucoup de points se perdent avant même la langue.', 3),
    ('a074680f-3471-5f7a-a884-65ba72e53142'::uuid, 'llcer-anglais', 'Tle', 'L’épreuve de LLCER en terminale', 'Qu’évalue le jury à l’oral, selon le cours ?', 'mcq', '["La récitation d’un texte appris","La longueur de la présentation","L’accent britannique","La réaction face aux questions imprévues"]'::jsonb, 3, 'D’où le conseil de s’entraîner en se faisant poser des questions inattendues.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

-- 3. Sonde finale ---------------------------------------------------------
