   WHERE id IN ('fe06c175-bfb2-59a7-b481-07fead8ce332'::uuid, 'a2a85cbb-bd6d-5345-9cf0-312c7cf95dad'::uuid, '6940b915-301e-55b9-8904-adc6f75bdcf2'::uuid, '07df9f0f-8496-5dd5-b9db-34ccc62d1be3'::uuid, 'e54832c5-3c13-5d42-aa3d-4486295ceb16'::uuid, 'b1efec0d-0736-505d-87ea-8cccff5b14f3'::uuid, 'a3bc1341-b1cd-508b-9a7b-d61787ac1ff1'::uuid, '6aa29f58-4c22-59e4-a727-efc9f5508722'::uuid, 'ed2c8838-434e-5201-a5ff-3bae780bb3d6'::uuid, '4cd8d824-9092-5103-9cde-f96362a0e1a4'::uuid, '91f10246-33e3-5047-982c-0f4183196146'::uuid, 'dde8550d-211c-5a43-aa5a-9719adbafcad'::uuid, 'e34877e4-fbbf-5f73-807f-b21fc4ea584e'::uuid, '1603f3bf-6e6f-5a40-89cf-6f0dc4dd768c'::uuid, '3d9d38dc-bcab-5616-b70e-c4772b233648'::uuid, 'db6f483e-b4cf-5377-be88-375af3e63420'::uuid, 'd5a675d4-7743-5292-9c17-006011ef4d9b'::uuid, '3398fcd9-ecc7-5a26-bdad-f4038fc28218'::uuid, 'd635db4e-a74e-5ec7-b93c-ea3a28118566'::uuid, '6bf0876f-8539-53c6-9882-7bada4c6f7f9'::uuid, '136382d5-e292-570f-ac1a-e16609785fe2'::uuid, '12a05b46-2d13-525c-b8d9-fc3cac066b0f'::uuid, 'bb736e23-100a-57a8-b72e-583a82aebc81'::uuid, '2afa154d-bead-54d8-83e6-cf4ea41ee407'::uuid, '7cde42f0-3465-5a3b-8fa0-ec13ad613cbc'::uuid, '3d6905a2-627f-5602-839b-54950eda535e'::uuid, 'b5673412-d49e-5ec3-8499-95ed3c74b2c1'::uuid, '29aeedd6-844c-5103-911b-77b952bc210c'::uuid, 'e362b905-df51-5a42-b9a3-67005a573648'::uuid, 'bc05d55e-ce70-5963-a86d-3449be5696f2'::uuid, '8ef9824c-4c17-5630-8226-34ea1e1ad335'::uuid, 'eab4e8f0-39f3-50fb-943a-e9c187488452'::uuid, '1ed4d847-9e12-5d4f-b368-30a60986eba6'::uuid, '4badb43a-1ea2-5ad6-8fce-abb49077bea0'::uuid, '28a1483f-f7c2-5c1b-bace-e9239db772ea'::uuid, '6cd8d9c4-1227-505a-abf6-dce6a8b28f2f'::uuid, '15773fb4-f7cf-5ab2-a065-51975651ce2a'::uuid, 'a346e278-2fb8-5a78-bd18-e27f5045975d'::uuid, '20149d5d-6028-5e65-a065-77452a9231d6'::uuid, '7cfb34a8-a3c6-53ff-8e22-860e01b13c6e'::uuid, 'cfac63ab-f8a9-5256-8775-af70050acdba'::uuid, '3254f432-b770-5a51-9abe-d3e87df34901'::uuid, 'a89b3084-f9bb-5238-b2ac-260afbd93d05'::uuid, 'ddf41